package mscmrp

import (
	"github.com/TheManticoreProject/Manticore/network/dcerpc/ndr"
	"github.com/TheManticoreProject/Manticore/windows/guid"
)

// CLUSDSK_DISKID ([MS-CMRP]). Generated by tools/idlgen; verify pointer/array tags.
type CLUSDSK_DISKID struct {
	DiskIdType CLUSDSK_DISKID_ENUM
	Field      CLUSDSK_DISKID_Field
}

// CLUSDSK_DISKID_Field is the [switch_is(DiskIdType)] union of _CLUSDSK_DISKID
// ([MS-CMRP] 2.2.3.10, [C706] 14.3.8). The discriminant is CLUSDSK_DISKID_ENUM
// (a 16-bit NDR enum), transmitted inline ahead of the selected arm; its width
// must match the sibling DiskIdType, so Tag is the enum type (2 octets under
// NDR20), not a 4-byte DWORD. Case values are the enum members
// DiskIdSignature (1) and DiskIdGuid (2).
type CLUSDSK_DISKID_Field struct {
	Tag           CLUSDSK_DISKID_ENUM `ndr:"switch"`
	DiskSignature ndr.DWORD           `ndr:"case=1"`
	DiskGuid      guid.GUID           `ndr:"case=2"`
}
